CREATE TABLE `instruments` (
	`symbol` text PRIMARY KEY NOT NULL,
	`name` text NOT NULL,
	`asset_type` text NOT NULL,
	`provider_type` text NOT NULL,
	`primary_exchange` text,
	`currency` text,
	`active` integer DEFAULT true NOT NULL,
	`color` text NOT NULL,
	`seed_hot` integer NOT NULL,
	`seed_not` integer NOT NULL,
	`source_updated_at` text,
	`synced_at` integer NOT NULL
);
--> statement-breakpoint
CREATE INDEX `idx_instruments_active_type_symbol` ON `instruments` (`active`,`asset_type`,`symbol`);--> statement-breakpoint
CREATE INDEX `idx_instruments_name` ON `instruments` (`name`);
